import numpy as np


def construct():
    """Greedy baseline: scan the grid row-major, add every point that keeps the set
    isosceles-free (an apex check in exact integer arithmetic). Deterministic."""
    n = 64
    pts = []
    seen = [set() for _ in range(n * n)]  # seen[i]: squared distances from point i to the set

    def ok(p):
        d2s = set()
        for q in pts:
            d2 = (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2
            if d2 in d2s or d2 in seen[q[0] * n + q[1]]:
                return None
            d2s.add(d2)
        return d2s

    for x in range(n):
        for y in range(n):
            p = (x, y)
            d2s = ok(p)
            if d2s is not None:
                seen[p[0] * n + p[1]] = d2s
                for q in pts:
                    seen[q[0] * n + q[1]].add((p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2)
                pts.append(p)
    return [list(p) for p in pts]

import time
import random

def construct():
    """
    Improved multi-start greedy with:
    - diverse deterministic seed orders (center-first, corners-first, spiral)
    - time-bounded restarts (with lightweight perturbations)
    - lightweight local repair: remove 1-3 points from current best and refill
    - fast per-candidate checks using simple distance calculations
    """
    n = 64
    all_pts = [(x, y) for x in range(n) for y in range(n)]
    best_sol = []
    best_len = 0

    start_time = time.time()
    TIME_LIMIT = 4.0  # seconds

    # 1) Deterministic seed orders
    center = ( (n - 1) / 2.0, (n - 1) / 2.0 )

    def center_order():
        cx, cy = center
        def key(p):
            x, y = p
            dman = abs(x - cx) + abs(y - cy)
            d2 = (x - cx)**2 + (y - cy)**2
            return (dman, d2)
        return sorted(all_pts, key=key)

    corners = [(0,0),(0,n-1),(n-1,0),(n-1,n-1)]
    def corners_order():
        cx, cy = center
        def key(p):
            x, y = p
            d_corner = min((x - cx2)**2 + (y - cy2)**2 for cx2, cy2 in corners)
            d_center = (x - cx)**2 + (y - cy)**2
            return (d_corner, d_center)
        return sorted(all_pts, key=key)

    def spiral_order():
        cx, cy = center
        order = []
        maxr = max(n-1, n-1)
        for r in range(0, maxr + 1):
            x0, x1 = int(round(cx - r)), int(round(cx + r))
            y0, y1 = int(round(cy - r)), int(round(cy + r))
            # top
            if 0 <= y0 < n:
                for x in range(max(0, x0), min(n, x1 + 1)):
                    order.append((x, y0))
            # right
            if 0 <= x1 < n:
                for y in range(max(0, y0 + 1), min(n, y1 + 1)):
                    order.append((x1, y))
            # bottom
            if 0 <= y1 < n:
                for x in range(min(n - 1, x1 - 1), max(-1, x0 - 1), -1):
                    order.append((x, y1))
            # left
            if 0 <= x0 < n:
                for y in range(min(n - 1, y1 - 1), max(-1, y0 - 1), -1):
                    order.append((x0, y))
        seen = set()
        res = []
        for p in order:
            if p in seen:
                continue
            if 0 <= p[0] < n and 0 <= p[1] < n:
                res.append(p)
                seen.add(p)
        if len(res) < len(all_pts):
            for p in all_pts:
                if p not in seen:
                    res.append(p)
                    seen.add(p)
        return res

    seed_orders = [
        center_order(),
        corners_order(),
        spiral_order(),
    ]

    def greedy_build(order):
        pts = []          # list of (x,y)
        masks = []        # per point: set of distances to previously chosen points
        coords = []       # copy of selected coords

        for p in order:
            px, py = p
            if not pts:
                pts.append((px, py))
                coords.append((px, py))
                masks.append(set())
                continue

            # distances to existing
            d2s = []
            for (qx, qy) in coords:
                dx = px - qx
                dy = py - qy
                d2s.append(dx*dx + dy*dy)

            # 1) all d2s must be unique
            if len(set(d2s)) != len(d2s):
                continue

            # 2) for every existing i, d2s[i] must not already be in masks[i]
            ok = True
            for i, d2 in enumerate(d2s):
                if d2 in masks[i]:
                    ok = False
                    break
            if not ok:
                continue

            # Accept
            for i, d2 in enumerate(d2s):
                masks[i].add(d2)
            masks.append(set(d2s))
            coords.append((px, py))
            pts.append((px, py))

        return pts

    # Run deterministic seeds
    for so in seed_orders:
        sol = greedy_build(list(so))
        if len(sol) > best_len:
            best_sol = sol
            best_len = len(sol)

    # Randomized restarts with light perturbations
    pool = all_pts[:]
    random.shuffle(pool)

    while time.time() - start_time < TIME_LIMIT:
        random.shuffle(pool)
        order = pool[:]
        # mild perturbation if long
        if len(order) > 2000:
            step = max(1, len(order) // 8)
            for i in range(0, len(order), step):
                j = i + random.randint(0, min(50, len(order) - 1 - i))
                order[i], order[j] = order[j], order[i]

        sol = greedy_build(order)
        if len(sol) > best_len:
            best_sol = sol
            best_len = len(sol)

        # Lightweight local repair: try removing 1-3 from current best and refill
        if best_len >= 2:
            base = best_sol[:]
            for remove_k in (1, 2, 3):
                if best_len - remove_k <= 0:
                    continue
                if len(base) < remove_k:
                    continue
                idxs = random.sample(range(len(base)), remove_k)
                trial = [p for i, p in enumerate(base) if i not in idxs]
                # Refill using a shuffled pool order
                refill_order = pool[:]
                sol2 = greedy_build(trial + refill_order)
                if len(sol2) > best_len:
                    best_sol = sol2
                    best_len = len(sol2)

    # Final formatting: ensure JSON-serializable list of [int,int]
    return [ [int(x), int(y)] for (x, y) in best_sol ]

