def _validator(sol):
    # sol: list of (x,y)
    n = len(sol)
    # check bounds and uniqueness
    seen = set()
    for p in sol:
        if not (0 <= p[0] <= 63 and 0 <= p[1] <= 63):
            return False
        if tuple(p) in seen:
            return False
        seen.add(tuple(p))
    # verify no point has equal distances to two others (no isosceles)
    for i in range(n):
        d2s = []
        x1, y1 = sol[i]
        for j in range(n):
            if i == j:
                continue
            x2, y2 = sol[j]
            dx = x1 - x2
            dy = y1 - y2
            d2s.append(dx*dx + dy*dy)
        if len(d2s) != len(set(d2s)):
            return False
    return True

