                for x in range(min(n - 1, x1 - 1), max(-1, x0 - 1), -1):
                    order.append((x, y1))
            # left column
            if 0 <= x0 < n:
                for y in range(min(n - 1, y1 - 1), max(-1, y0 - 1), -1):
                    order.append((x0, y))
        # deduplicate while keeping order
        seen = set()
        res = []
        for p in order:
            if p not in seen:
                res.append(p)
                seen.add(p)
        # fallback: ensure full coverage
        if len(res) < len(all_pts):
            for p in all_pts:
                if p not in seen:
                    res.append(p)
                    seen.add(p)
        return res

    seed_orders = [
        center_order(),
        corners_order(),
        spiral_order(),
    ]

    def greedy_build(order):
        coords = []  # selected points
        masks = []   # per-point bitmask of distances seen from that point to existing points
        # masks[i] has bits set at positions d2 where distance from coords[i] to some earlier point equals d2
        for p in order:
            px, py = p
            if not coords:
                coords.append((px, py))
                masks.append(0)  # first point has no distances yet
                continue

            # distances to existing points
            d2s = []
            for (qx, qy) in coords:
                dx = px - qx
                dy = py - qy
