                    best_len = len(sol2)

    # Final validation: ensure no-isosceles
    if not _validator(best_sol):
        # Fallback: try to return a very small valid solution (at least non-empty)
        # Start from center and expand greedily deterministically once more
        center_pt = (63//2, 63//2)
        candidate = [list(center_pt)]
        # try to add around center with strict checks
        def can_add(p, current):
            xs = [q[0] for q in current]
            ys = [q[1] for q in current]
            ds = []
            for (qx, qy) in current:
                dx = p[0] - qx
                dy = p[1] - qy
                ds.append(dx*dx + dy*dy)
            if len(set(ds)) != len(ds):
                return False
            # per-existing check
            for i, d2 in enumerate(ds):
                # build masks on the fly
                # compute distances from i to others
                for j, other in enumerate(current):
                    if i == j:
                        continue
                    d2_ij = (current[i][0]-other[0])**2 + (current[i][1]-other[1])**2
                    if d2 == d2_ij:
                        return False
            return True
        # expand roughly 10 points around center
        for p in all_pts:
