                continue
            if can_add(p, candidate):
                candidate.append(list(p))
                if len(candidate) >= 5:
                    break
        best_sol = [(x, y) for x, y in candidate]

    # Final formatting
    final = [ [int(x), int(y)] for (x, y) in best_sol ]
    # Double-check final validity; if invalid, fall back to a tiny valid set
    if not _validator(best_sol):
        final = [ [0,0] ]
    return final

