def _is_valid_set(pts):
    # For every point, distances to all other points must be pairwise distinct
    n = len(pts)
    if n <= 1:
        return True
    for i in range(n):
        d2set = set()
        xi, yi = pts[i]
        for j in range(n):
            if i == j:
                continue
            xj, yj = pts[j]
            dx = xi - xj
            dy = yi - yj
            d2 = dx*dx + dy*dy
            if d2 in d2set:
                return False
            d2set.add(d2)
    return True

