    center = ( (n - 1) / 2.0, (n - 1) / 2.0 )

    def center_order():
        cx, cy = center
        def key(p):
            x, y = p
            dman = abs(x - cx) + abs(y - cy)
            d2 = (x - cx)**2 + (y - cy)**2
            return (dman, d2)
        return sorted(pts_all, key=key)

    corners = [(0,0), (0,n-1), (n-1,0), (n-1,n-1)]
    def corners_order():
        cx, cy = center
        def key(p):
            x, y = p
            d_corner = min((x - cx2)**2 + (y - cy2)**2 for (cx2, cy2) in corners)
            d_center = (x - cx)**2 + (y - cy)**2
            return (d_corner, d_center)
        return sorted(pts_all, key=key)

    def spiral_order():
        cx, cy = center
        order = []
        maxr = max(n-1, n-1)
        for r in range(0, maxr+1):
            x0, x1 = int(round(cx - r)), int(round(cx + r))
            y0, y1 = int(round(cy - r)), int(round(cy + r))
            if 0 <= y0 < n:
                for x in range(max(0, x0), min(n, x1+1)):
                    order.append((x, y0))
            if 0 <= x1 < n:
                for y in range(max(0, y0+1), min(n, y1+1)):
                    order.append((x1, y))
            if 0 <= y1 < n:
                for x in range(min(n-1, x1-1), max(-1, x0-1), -1):
                    order.append((x, y1))
            if 0 <= x0 < n:
                for y in range(min(n-1, y1-1), max(-1, y0, -1), -1):
                    order.append((x0, y))
        seen = set()
        res = []
        for p in order:
            if p in seen:
                continue
            if 0 <= p[0] < n and 0 <= p[1] < n:
                res.append(p)
                seen.add(p)
        if len(res) < len(pts_all):
            for p in pts_all:
                if p not in seen:
                    res.append(p)
                    seen.add(p)
        return res

    seed_orders = [
        center_order(),
        corners_order(),
        spiral_order(),
    ]

    # Greedy builder with per-point distance histories
    # dist_sets[i] stores the set of squared distances from pts[i] to all points with index < i
    def greedy_build(order):
        pts = []          # chosen coordinates
        dist_sets = []    # list of sets: distances from existing i to all earlier points

        for p in order:
            px, py = p
            if not pts:
                pts.append((px, py))
                dist_sets.append(set())
                continue

            # Distances to all existing points
            d2s = []
            for (qx, qy) in pts:
                dx = px - qx
                dy = py - qy
                d2s.append(dx*dx + dy*dy)

            # Constraint 1: all d2s must be pairwise distinct
            if len(set(d2s)) != len(d2s):
                continue

            # Constraint 2: for each existing i, d2s[i] must be new w.r.t dist_sets[i]
            ok = True
            for i, d2 in enumerate(d2s):
                if d2 in dist_sets[i]:
                    ok = False
                    break
            if not ok:
                continue

            # Accept: update structures
            for i, d2 in enumerate(d2s):
                dist_sets[i].add(d2)
            dist_sets.append(set(d2s))
            pts.append((px, py))

        return pts

    # Run deterministic seeds
    for so in seed_orders:
        sol = greedy_build(list(so))
        if len(sol) > best_len:
            best_sol = sol
            best_len = len(sol)

    # Randomized restarts with lightweight repair
    pool = pts_all[:]
    random.shuffle(pool)

    def lightweight_repair(base_sol):
        if len(base_sol) <= 1:
            return base_sol
        best_local = base_sol
        # Try removing 1-2 points and refilling
        for remove_k in (1, 2):
            if len(base_sol) <= remove_k:
                continue
            idxs = random.sample(range(len(base_sol)), remove_k)
            trial = [p for i, p in enumerate(base_sol) if i not in idxs]
            refill_order = pool[:]
            random.shuffle(refill_order)
            sol = greedy_build(trial + refill_order)
            if len(sol) > len(best_local):
                best_local = sol
        return best_local

    # Main loop
    while time.time() - start_time < TIME_LIMIT:
        order = pool[:]
        random.shuffle(order)

        # Slight bias to structured perturbations
        if len(order) > 2000:
            step = max(1, len(order) // 8)
            for i in range(0, len(order), step):
                j = i + random.randint(0, min(50, len(order) - 1 - i))
                order[i], order[j] = order[j], order[i]

        sol = greedy_build(order)
        if len(sol) > best_len:
            best_sol = sol
            best_len = len(sol)

        # Lightweight repair on current best
        if best_len >= 2:
            repaired = lightweight_repair(best_sol)
            if len(repaired) > best_len:
                best_sol = repaired
                best_len = len(repaired)

        # Small perturbation hill-climb
        if len(best_sol) > 0:
            perturb = best_sol[:]
            k = min(3, len(perturb))
            if k > 0:
                idxs = random.sample(range(len(perturb)), k)
                for idx in sorted(idxs, reverse=True):
                    perturb.pop(idx)
                insert_positions = [random.randint(0, len(perturb)) for _ in range(k)]
                for p, pos in zip([best_sol[i] for i in idxs], insert_positions):
                    perturb.insert(pos, p)
                sol2 = greedy_build(perturb + pool)
                if len(sol2) > best_len:
                    best_sol = sol2
                    best_len = len(sol2)

    # Final validation: brute-force per pivot distances
    def final_validate(solution):
        m = len(solution)
        for i in range(m):
            pi = solution[i]
            di = []
            for j in range(m):
                if i == j:
                    continue
                pj = solution[j]
                dx = pi[0] - pj[0]
                dy = pi[1] - pj[1]
                di.append(dx*dx + dy*dy)
            if len(set(di)) != len(di):
                return False
        return True

    if not final_validate(best_sol):
        # Fallback to a minimal valid set
        best_sol = [(0, 0)]
        best_len = 1

    return [[int(x), int(y)] for (x, y) in best_sol]

