    for i in range(n):
        xi, yi = pts[i]
        seen = set()
        for j in range(n):
            if i == j:
                continue
            xj, yj = pts[j]
            d2 = (xi - xj)*(xi - xj) + (yi - yj)*(yi - yj)
            if d2 in seen:
                return False
            seen.add(d2)
    return True

