        for (qx, qy) in coords:
            dx = px - qx
            dy = py - qy
            d2s.append(dx*dx + dy*dy)

        # 1) All distances to existing points must be unique
        if len(set(d2s)) != len(d2s):
            continue

        # 2) For each existing i, d2s[i] must not already appear in masks[i]
        ok = True
        for i, d2 in enumerate(d2s):
            if d2 in masks[i]:
                ok = False
                break
        if not ok:
            continue

        # Accept candidate
        for i, d2 in enumerate(d2s):
            masks[i].add(d2)
        masks.append(set(d2s))
        coords.append((px, py))
        pts.append((px, py))

    return pts

